1	"use client";
2	
3	import React, { useEffect, useRef, useState } from 'react';
4	import { Sidebar } from '@/components/Sidebar';
5	import { FileSidebar } from '@/components/FileSidebar';
6	import { SliceSidebar } from '@/components/SliceSidebar';
7	import { CategoriesSidebar } from '@/components/CategoriesSidebar';
8	import { PrinterConfigSidebar } from '@/components/PrinterConfigSidebar';
9	import { AxisSidebar } from '@/components/AxisSidebar';
10	import { ModelingSidebar } from '@/components/ModelingSidebar';
11	import { TopRightMenu } from '@/components/TopRightMenu';
12	import { ModelStatusBox } from '@/components/ModelStatusBox';
13	import { ModelHoverTooltip } from '@/components/ModelHoverTooltip';
14	import { TextureEditorModal } from '@/components/TextureEditorModal';
15	import { SliceModal } from '@/components/SliceModal';
16	import { SlicingProgressModal } from '@/components/SlicingProgressModal';
17	import { ViewCube } from '@/components/ViewCube';
18	import { Viewport3D } from '@/components/Viewport3D';
19	import { SpaceTransitionOverlay } from '@/components/SpaceTransitionOverlay';
20	import { GCodePreview } from '@/components/GCodePreview';
21	import { useAnimate } from 'framer-motion';
22	import { Box } from 'lucide-react';
23	import { showSuccess } from '@/utils/toast';
24	
25	interface ModelStatus {
26	  name: string;
27	  dimensions: { x: number; y: number; z: number } | null;
28	}
29	
30	const Index = () => {
31	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer'>('3d-view');
32	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
33	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
34	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
35	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
36	  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
37	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
38	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
39	  const [isPreviewActive, setIsPreviewActive] = useState(false);
40	  const isPreviewActiveRef = useRef(isPreviewActive);
41	  isPreviewActiveRef.current = isPreviewActive;
42	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
43	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
44	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
45	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
46	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
47	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
48	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
49	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
50	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
51	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
52	  // de risque de clignotement à la jonction.
53	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
54	  // Vrai dès le CLIC vers Modélisation (cf. l'écouteur d'apex-entering-modeling plus bas), jamais
55	  // seulement à `onCovered` (~900ms plus tard, une fois le rideau refermé) : le fondu-glissement du
56	  // panneau du bas de Prévisualisation doit être visible EN TRANSPARENCE À TRAVERS le rideau qui
57	  // monte, pas caché derrière lui — contrairement au vrai changement d'onglet (`onTabChange`), qui
58	  // lui reste cadencé par `onCovered`. Redevient faux une fois le morph 'enter' effectivement lancé
59	  // (le panneau du bas a alors largement eu le temps de finir sa disparition, 260ms contre les
60	  // ~900ms d'attente du rideau).
61	  const [leavingToModeling, setLeavingToModeling] = useState(false);
62	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
63	  const prevPreviewActiveRef = useRef(isPreviewActive);
64	
65	  // Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
66	  // se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
67	  // (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
68	  // arrivée (1,1 s), pour ne pas se faire recouvrir.
69	  useEffect(() => {
70	    if (prevPreviewActiveRef.current === isPreviewActive) return;
71	    prevPreviewActiveRef.current = isPreviewActive;
72	    if (!statusBarRef.current) return;
73	    animateStatusBar(
74	      statusBarRef.current,
75	      { y: [0, 0, 80, 80, 0] },
76	      { duration: 1.4, times: [0, 0.2 / 1.4, 0.45 / 1.4, 1.1 / 1.4, 1], ease: [0.25, 1, 0.5, 1] },
77	    );
78	  }, [isPreviewActive, animateStatusBar, statusBarRef]);
79	
80	  /** L'onglet « Modélisation » de la Sidebar porte la valeur 'settings'. */
81	  const isModeling = activeTab === 'settings';
82	
83	  // Une fois CategoriesSidebar (et son panneau du bas) effectivement démontée par le passage en
84	  // Modélisation, `leavingToModeling` peut redescendre : il n'a plus d'effet visuel à cet instant
85	  // (le fondu est terminé depuis longtemps), mais doit être prêt (`false`) pour un futur cycle.
86	  useEffect(() => {
87	    if (isModeling) setLeavingToModeling(false);
88	  }, [isModeling]);
89	
90	  // Vrai du début d'un morph de sortie de Modélisation jusqu'au commit qui le termine, où
91	  // CategoriesSidebar est remontée et le lit (une seule fois, à son montage). Remis à `false` juste
92	  // après, une fois ce montage passé.
93	  const [arrivingFromModeling, setArrivingFromModeling] = useState(false);
94	  useEffect(() => {
95	    if (!modelingMorph) setArrivingFromModeling(false);
96	  }, [modelingMorph]);
97	
98	  React.useEffect(() => {
99	    const handleModelSelected = (event: CustomEvent<{
100	      name: string | null;
101	      dimensions?: { x: number; y: number; z: number };
102	    }>) => {
103	      if (!event.detail?.name) {
104	        setModelStatus(null);
105	        return;
106	      }
107	
108	      setModelStatus({
109	        name: event.detail.name,
110	        dimensions: event.detail.dimensions ?? null,
111	      });
112	    };
113	
114	    const handleModelImported = (event: CustomEvent<File>) => {
115	      if (event.detail?.name) {
116	        setModelStatus({ name: event.detail.name, dimensions: null });
117	      }
118	    };
119	
120	    const handlePreviewToggled = (event: CustomEvent<{ active: boolean }>) => {
121	      setIsPreviewActive(!!event.detail?.active);
122	    };
123	
124	    // Dispatché par Sidebar.tsx (handleTopTabClick) au tout début du clic vers Modélisation, avant
125	    // même que le rideau plein écran ne commence à monter — cf. le commentaire sur
126	    // `leavingToModeling` plus haut.
127	    const handleEnteringModeling = () => setLeavingToModeling(true);
128	
129	    window.addEventListener('apex-mesh-selected', handleModelSelected as EventListener);
130	    window.addEventListener('apex-import-model', handleModelImported as EventListener);
131	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
132	    window.addEventListener('apex-entering-modeling', handleEnteringModeling);
133	
134	    return () => {
135	      window.removeEventListener('apex-mesh-selected', handleModelSelected as EventListener);
136	      window.removeEventListener('apex-import-model', handleModelImported as EventListener);
137	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
138	      window.removeEventListener('apex-entering-modeling', handleEnteringModeling);
139	    };
140	  }, []);
141	
142	  const handleSlice = () => {
143	    window.dispatchEvent(new CustomEvent('apex-request-slice-models'));
144	    setIsSliceModalOpen(true);
145	  };
146	
147	  const handleConfirmSlice = () => {
148	    window.dispatchEvent(new CustomEvent('apex-slice-all-models'));
149	    setIsSliceModalOpen(false);
150	    setIsSlicingProgressOpen(true);
151	  };
152	
153	  const handleSlicingFinished = () => {
154	    setIsSlicingProgressOpen(false);
155	    showSuccess("Slicing plate completed successfully!");
156	  };
157	
158	  const handleOpenModel = () => {
159	    showSuccess("Select an STL or GLB file to add a model.");
160	  };
161	
162	  const handleSaveProject = () => {
163	    showSuccess("Project saved successfully.");
164	  };
165	
166	  return (
167	    <div
168	      className="flex flex-col h-screen w-screen overflow-hidden select-none relative"
169	      style={{ backgroundColor: '#2a2d34' }}
170	    >
171	      <FileSidebar 
172	        onOpenModel={handleOpenModel}
173	        onSaveProject={handleSaveProject}
174	        onOpenSettings={() => setActiveTab('settings')}
175	        onOpenPrinterConfig={() => {
176	          setIsPrinterConfigOpen(!isPrinterConfigOpen);
177	          setActiveCategory(null);
178	        }}
179	        selectedPrinter={selectedPrinter}
180	        selectedFilament={selectedFilament}
181	      />
182	
183	      <ModelStatusBox />
184	      <ModelHoverTooltip />
185	      <TextureEditorModal />
186	      <SliceModal
187	        isOpen={isSliceModalOpen}
188	        onClose={() => setIsSliceModalOpen(false)}
189	        onConfirm={handleConfirmSlice}
190	      />
191	      <SlicingProgressModal
192	        isOpen={isSlicingProgressOpen}
193	        onClose={() => setIsSlicingProgressOpen(false)}
194	        onFinished={handleSlicingFinished}
195	      />
196	
197	      <Sidebar
198	        activeTab={activeTab}
199	        onTabChange={(tab, toPreview) => {
200	          // Passage vers ou hors de Modélisation : le rideau plein écran (déjà déclenché par
201	          // Sidebar avant cet appel, cf. playSpaceTransition) masque le changement de `main`,
202	          // pendant lequel ModelingSidebar (montée en permanence tant que isModeling ||
203	          // modelingMorph) joue le morph — cf. son prop `morph`.
204	          if (tab === 'settings' && !isModeling) {
205	            // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
206	            // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
207	            // Les éléments sans place en Modélisation ont déjà disparu depuis le clic
208	            // (apex-entering-modeling, ~900ms plus tôt) : la déformation peut commencer tout de
209	            // suite, dans le même commit que la bascule CategoriesSidebar → ModelingSidebar.
210	            setModelingMorph({ direction: 'enter', fromPreview: isPreviewActiveRef.current });
211	          } else if (tab !== 'settings' && isModeling) {
212	            // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
213	            // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
214	            // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
215	            setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
216	            setArrivingFromModeling(true);
217	          }
218	          setActiveTab(tab === 'box' ? '3d-view' : tab);
219	          setIsPrinterConfigOpen(false);
220	        }}
221	        onOpenModel={handleOpenModel}
222	      />
223	
224	      <TopRightMenu />
225	      <AxisSidebar />
226	      <ViewCube />
227	
228	      {/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement. La bascule se fait
229	          TOUJOURS dans un seul commit, par un rendu conditionnel simple — jamais via
230	          AnimatePresence, qui retarde le démontage de l'ancien côté (et en mode 'wait', le
231	          montage du nouveau) d'au moins une tâche, donc d'au moins une frame peinte. Toute
232	          l'animation visible est portée ailleurs : la déformation par ModelingSidebar (prop
233	          `morph`), les fondus par `animate` dès le clic. */}
234	      {isModeling || modelingMorph?.direction === 'exit' ? (
235	        <ModelingSidebar
236	          morph={
237	            modelingMorph
238	              ? { ...modelingMorph, onDone: () => setModelingMorph(null) }
239	              : undefined
240	          }
241	        />
242	      ) : (
243	          <>
244	            <CategoriesSidebar
245	              activeCategory={activeCategory}
246	              onSelectCategory={(cat) => {
247	                setActiveCategory(cat);
248	                if (cat) setIsPrinterConfigOpen(false);
249	              }}
250	              // Remonté à la fin d'un morph de sortie de Modélisation : ce composant doit apparaître
251	              // directement dans la forme que ModelingSidebar vient de prendre (pilule ou panneaux
252	              // de Prévisualisation), sans rejouer d'entrée ni de mitose. Ces deux props ne sont lues
253	              // qu'au montage (figées en interne).
254	              initialPreviewActive={isPreviewActive}
255	              arrivingFromModeling={arrivingFromModeling}
256	              leavingToModeling={leavingToModeling}
257	            />
258	
259	            <PrinterConfigSidebar
260	              isOpen={isPrinterConfigOpen}
261	              onClose={() => setIsPrinterConfigOpen(false)}
262	              selectedPrinter={selectedPrinter}
263	              onSelectPrinter={setSelectedPrinter}
264	              selectedFilament={selectedFilament}
265	              onSelectFilament={setSelectedFilament}
266	            />
267	
268	            <SliceSidebar onSlice={handleSlice} />
269	          </>
270	      )}
271	
272	      <main className="flex-1 flex flex-col relative overflow-hidden z-10 bg-transparent">
273	        <div className="flex-1 w-full h-full">
274	          <Viewport3D />
275	        </div>
276	
277	        {/* Espace Prévisualisation : interface du prévisualisateur G-code polaire. Le tracé
278	            lui-même est rendu par Viewport3D, dans la même scène que la Préparation. Toujours
279	            monté pour conserver le fichier chargé d'un aller-retour à l'autre. */}
280	        <GCodePreview active={isPreviewActive} />
281	
282	        {/* À l'intérieur de `main` (donc borné à l'espace 3D) et sous les panneaux `position:
283	            fixed` (sidebars, menus, tooltips, z-index 1000+) : le flou et le voile ne doivent
284	            couvrir que le viewport, jamais les éléments en superposition. */}
285	        <SpaceTransitionOverlay />
286	
287	        {/* Bottom status / stats overlay — au-dessus du rideau de transition (z-index 30) pour
288	            ne pas être flouté, comme les panneaux fixes. */}
289	        <div ref={statusBarRef} className="absolute bottom-4 left-4 right-24 z-40 flex items-center justify-start pointer-events-none">
290	          <div className="bg-[rgba(10,15,26,0.25)] backdrop-blur-[4px] -webkit-backdrop-blur-[4px] border-none rounded-lg px-3 py-2 text-xs text-zinc-300 flex items-center space-x-4 pointer-events-auto shadow-[0_8px_32px_0_rgba(0,0,0,0.4),0_2px_8px_0_rgba(0,0,0,0.3)]">
291	            {modelStatus ? (
292	              <>
293	                <span className="flex items-center"><Box className="w-3.5 h-3.5 mr-1.5 text-blue-400" /> {modelStatus.name}</span>
294	                {modelStatus.dimensions && (
295	                  <>
296	                    <span className="text-zinc-600">|</span>
297	                    <span>Dimensions: {modelStatus.dimensions.x.toFixed(1)} x {modelStatus.dimensions.z.toFixed(1)} x {modelStatus.dimensions.y.toFixed(1)} mm</span>
298	                  </>
299	                )}
300	                <span className="text-zinc-600">|</span>
301	                <span className="text-emerald-400 font-medium">Ready to slice</span>
302	              </>
303	            ) : (
304	              <span className="text-zinc-400">Aucun modèle sur le plateau</span>
305	            )}
306	          </div>
307	        </div>
308	      </main>
309	    </div>
310	  );
311	};
312	
313	export default Index;

