1	import React, { useState, useRef, useEffect } from 'react';
2	import { motion, Variants } from 'framer-motion';
3	import clsx from 'clsx';
4	import {
5	  FileSliders,
6	  Box,
7	  MousePointer2,
8	  Move3d,
9	  RotateCw,
10	  Maximize,
11	  Upload,
12	  Code,
13	  Maximize2,
14	  Eye,
15	  Palette,
16	  Layers
17	} from 'lucide-react';
18	import styles from './Sidebar.module.scss';
19	import { CustomTooltip } from './CustomTooltip';
20	import { playUiSound, type UiSoundName } from '@/utils/uiSound';
21	
22	// Doit correspondre à ViewCube.module.scss (`.container`) : la colonne d'outils du mode
23	// Prévisualisation vient se coller au même bord droit, juste sous le gizmo.
24	const VIEWCUBE_RIGHT = 24;
25	const VIEWCUBE_BOTTOM = 70 + 130; // top + height
26	const PREVIEW_TOOLBAR_TOP_GAP = 10; // marge entre le bas du ViewCube et le haut de la colonne
27	const PREVIEW_TOOLBAR_WIDTH = 56; // largeur de la colonne de calques en mode Prévisualisation
28	
29	// Position de repos (mode box, sans transformation) du haut de `.bottomToolbar` : top du
30	// `.container` (20px) + hauteur du `.topToolbar` (42px de bouton + 8px de padding de
31	// chaque côté = 58px) + le gap de la pile flex (10px). Doit rester en phase avec
32	// Sidebar.module.scss si ces valeurs changent.
33	const BOTTOM_TOOLBAR_REST_TOP = 20 + 58 + 10;
34	
35	// Durée totale de l'animation de déplacement/déformation du conteneur `.bottomToolbar`
36	// (voir son `transition` plus bas) : c'est le délai avant lequel les icônes du mode cible
37	// ne doivent JAMAIS commencer à apparaître (cf. `iconVariants.visible`), dans tous les sens
38	// de transition. Partagée par les deux pour qu'elles ne puissent pas diverger.
39	const CONTAINER_RESHAPE_DURATION = 1.1;
40	
41	interface SidebarProps {
42	  activeTab: '3d-view' | 'settings' | 'developer';
43	  /**
44	   * `toPreview` n'est vrai que pour l'unique cas où `tab === 'box'` signifie « vers
45	   * Prévisualisation » plutôt que « vers Préparation » (cf. handleLayerClick, branche `entering`) —
46	   * Index.tsx en a besoin pour savoir, en sortant de Modélisation, vers quelle forme (pilule ou
47	   * panneaux de Prévisualisation) jouer le morph.
48	   */
49	  onTabChange: (tab: 'box' | 'settings' | 'developer', toPreview?: boolean) => void;
50	  onOpenModel?: () => void;
51	}
52	
53	export const Sidebar: React.FC<SidebarProps> = ({
54	  activeTab,
55	  onTabChange,
56	  onOpenModel
57	}) => {
58	  const [activeTool, setActiveTool] = useState<'select' | 'move' | 'rotate' | 'scale' | 'texture' | 'layers'>('select');
59	  const [isPreviewActive, setIsPreviewActive] = useState(false);
60	  // Géométrie du conteneur juste avant de lancer la transition en cours : mesurée à la volée
61	  // (voir `playSpaceTransition`) quel que soit le mode de départ (slicer, prévisualisation
62	  // ou modélisation), pour que l'animation de conteneur parte toujours de sa forme réelle et
63	  // non d'une valeur figée valable pour un seul sens de transition.
64	  const [fromGeometry, setFromGeometry] = useState<{ x: number; y: number; width: number; height: number; borderRadius: number } | null>(null);
65	  // Largeur naturelle de la barre slicer (mode "box") : son contenu (8 boutons + 2
66	  // séparateurs) ne change jamais, donc une mesure une fois montée suffit — c'est la valeur
67	  // cible numérique vers laquelle animer au retour au mode slicer (une keyframe `"auto"`
68	  // mélangée à des nombres dans le même tableau n'anime pas correctement avec framer-motion).
69	  const [boxWidth, setBoxWidth] = useState<number | null>(null);
70	  // Décalage horizontal (en x) à appliquer en mode Prévisualisation pour que la colonne
71	  // d'outils vienne se coller au bord droit de l'écran, juste sous le gizmo ViewCube
72	  // (position fixe à `right: 24px`, voir ViewCube.module.scss) — recalculé au resize car
73	  // `.bottomToolbar` est centré par le flex column de `.container` (`left: 50%`), donc son
74	  // décalage nécessaire dépend de la largeur de la fenêtre.
75	  const [previewX, setPreviewX] = useState(0);
76	  // Décalage vertical (en y) additionnel en mode Prévisualisation, calculé pour amener le
77	  // haut de la colonne juste sous le ViewCube, quelle que soit sa position de repos réelle
78	  // (dépend de la hauteur du bandeau d'onglets du haut).
79	  const [previewY, setPreviewY] = useState(0);
80	  const bottomToolbarRef = useRef<HTMLDivElement>(null);
81	  const fileInputRef = useRef<HTMLInputElement>(null);
82	
83	  const topToolbarRef = useRef<HTMLDivElement>(null);
84	  // Slot où ModelingSidebar injecte ses boutons CAD via un portail (id stable plutôt qu'un
85	  // ref transmis en prop : les deux composants sont des siblings montés indépendamment dans
86	  // Index.tsx, un id DOM est la façon la plus simple de se retrouver).
87	  const modelingSlotRef = useRef<HTMLDivElement>(null);
88	  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
89	  const [indicatorStyle, setIndicatorStyle] = React.useState<React.CSSProperties>({});
90	
91	  /** L'onglet « Modélisation » porte la valeur 'settings'. */
92	  const isModeling = activeTab === 'settings';
93	
94	  // Gabarit cible du conteneur commun pour chaque mode — voir le commentaire au-dessus de
95	  // `.bottomToolbar` dans le JSX pour la logique d'animation qui s'en sert. En mode
96	  // Prévisualisation, x/y viennent coller la colonne au bord droit de l'écran juste sous le
97	  // ViewCube (voir l'effet qui calcule `previewX`/`previewY` plus haut) plutôt qu'un
98	  // décalage fixe indépendant de la largeur de la fenêtre.
99	  const targetGeometry = isModeling
100	    ? { x: 0, y: 0, width: 260, height: 50, borderRadius: 14 } // barre CAD (6 boutons de 38px)
101	    : isPreviewActive
102	      ? { x: previewX, y: previewY, width: PREVIEW_TOOLBAR_WIDTH, height: 340, borderRadius: 20 } // colonne de calques
103	      : { x: 0, y: 0, width: boxWidth ?? 332, height: 44, borderRadius: 22 }; // barre slicer
104	
105	  const handleUploadClick = () => {
106	    fileInputRef.current?.click();
107	  };
108	
109	  const SPACE_LABELS: Record<'box' | 'settings' | 'developer' | 'layers', string> = {
110	    box: 'Préparation',
111	    settings: 'Modélisation',
112	    developer: 'Dev',
113	    layers: 'Prévisualisation',
114	  };
115	
116	  // Son propre à l'espace d'arrivée. Pas de son pour la console Dev.
117	  const SPACE_SOUNDS: Record<'box' | 'settings' | 'developer' | 'layers', UiSoundName | null> = {
118	    box: 'spacePreparation',
119	    settings: 'spaceModeling',
120	    developer: null,
121	    layers: 'spacePreview',
122	  };
123	
124	  /**
125	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
126	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
127	   * avoir lieu pour ne jamais être visible pendant la transition. Mesure aussi la forme
128	   * actuelle du conteneur d'outils juste avant : quel que soit le mode de départ (slicer,
129	   * prévisualisation ou modélisation), c'est de là que doit partir l'animation de
130	   * déformation vers le mode suivant — jamais une valeur figée valable pour un seul sens.
131	   */
132	  const playSpaceTransition = (space: keyof typeof SPACE_LABELS, onCovered: () => void) => {
133	    const label = SPACE_LABELS[space];
134	    const sound = SPACE_SOUNDS[space];
135	    if (sound) playUiSound(sound);
136	    if (bottomToolbarRef.current) {
137	      const rect = bottomToolbarRef.current.getBoundingClientRect();
138	      const computedRadius = parseFloat(getComputedStyle(bottomToolbarRef.current).borderTopLeftRadius) || 22;
139	      // `x`/`y` ne sont pas lisibles depuis le DOM (ce sont des translate posés par
140	      // framer-motion, pas une position absolue) : on reprend ceux du mode qu'on est en
141	      // train de quitter, calculés par la même table que `targetGeometry` ci-dessous.
142	      setFromGeometry({
143	        x: targetGeometry.x,
144	        y: targetGeometry.y,
145	        width: rect.width,
146	        height: rect.height,
147	        borderRadius: computedRadius,
148	      });
149	    }
150	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
151	  };
152	
153	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer') => {
154	    if (tabName === 'settings' && !isModeling) {
155	      // Signale DÈS LE CLIC — avant même que le rideau plein écran ne commence à monter, pas
156	      // seulement une fois l'écran couvert (`onCovered`, ~900ms plus tard) — que les éléments sans
157	      // place dans l'espace Modélisation (ModelStatusBox, panneau du bas de Prévisualisation)
158	      // doivent commencer à disparaître : ce fondu-glissement doit être visible EN TRANSPARENCE À
159	      // TRAVERS le rideau (z-index 1000+ pour ces éléments, contre 30 pour le rideau), jamais
160	      // caché derrière lui comme le vrai changement d'onglet (`onTabChange`, lui, reste dans
161	      // `onCovered` ci-dessous : le panneau Modélisation ne doit apparaître qu'une fois l'écran
162	      // couvert).
163	      window.dispatchEvent(new CustomEvent('apex-entering-modeling'));
164	    } else if (tabName !== 'settings' && isModeling) {
165	      // Symétrique : le contenu du panneau Modélisation disparaît en cascade dès le clic, avant
166	      // que sa forme ne commence à se déformer (à `onCovered`, cf. ModelingSidebar).
167	      window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
168	    }
169	    playSpaceTransition(tabName, () => {
170	      setActiveTool('select');
171	      onTabChange(tabName);
172	      setIsPreviewActive(false);
173	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
174	    });
175	  };
176	
177	  const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
178	    const newTool = activeTool === tool ? 'select' : tool;
179	    setActiveTool(newTool);
180	    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
181	  };
182	
183	  const handleLayerClick = () => {
184	    const entering = activeTool !== 'layers';
185	
186	    if (entering) {
187	      // Depuis Modélisation : même signal au clic que handleTopTabClick (cf. apex-leaving-modeling).
188	      if (isModeling) window.dispatchEvent(new CustomEvent('apex-leaving-modeling'));
189	      // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
190	      // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
191	      // d'un coup sous le voile plutôt qu'en deux temps visibles.
192	      playSpaceTransition('layers', () => {
193	        setActiveTool('layers');
194	        // Prévisualisation est un sous-mode du slicer (Préparation), jamais de la
195	        // Modélisation : sans ce `onTabChange`, entrer en Prévisualisation depuis
196	        // Modélisation laissait `activeTab` sur 'settings', et donc le bouton
197	        // "Modélisation" restait actif (cyan) par-dessus "Prévisualisation". Le second argument
198	        // signale spécifiquement ce cas-là à Index.tsx (venant de Modélisation, vers
199	        // Prévisualisation et non vers Préparation), pour qu'il joue le bon morph de sortie.
200	        onTabChange('box', true);
201	        setIsPreviewActive(true);
202	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
203	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
204	      });
205	    } else {
206	      playSpaceTransition('box', () => {
207	        setActiveTool('select');
208	        setIsPreviewActive(false);
209	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
210	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
211	      });
212	    }
213	  };
214	
215	  useEffect(() => {
216	    const handleKeyDown = (e: KeyboardEvent) => {
217	      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) {
218	        return;
219	      }
220	
221	      const key = e.key.toLowerCase();
222	      if (key === 'm') {
223	        const newTool = activeTool === 'move' ? 'select' : 'move';
224	        setActiveTool(newTool);
225	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
226	      } else if (key === 'r') {
227	        const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
228	        setActiveTool(newTool);
229	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
230	      } else if (key === 's') {
231	        const newTool = activeTool === 'scale' ? 'select' : 'scale';
232	        setActiveTool(newTool);
233	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
234	      } else if (key === 't') {
235	        const newTool = activeTool === 'texture' ? 'select' : 'texture';
236	        setActiveTool(newTool);
237	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
238	      } else if (key === 'escape') {
239	        setActiveTool('select');
240	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
241	      }
242	    };
243	
244	    window.addEventListener('keydown', handleKeyDown);
245	    return () => {
246	      window.removeEventListener('keydown', handleKeyDown);
247	    };
248	  }, [activeTool]);
249	
250	  // Mesure la largeur naturelle de la barre slicer dès qu'on la voit au repos (mode box,
251	  // aucune transition en cours) — la toute première fois, et à nouveau si jamais elle
252	  // n'a pas encore été capturée (ex : l'app démarre directement sur un autre onglet).
253	  useEffect(() => {
254	    if (boxWidth === null && !isModeling && !isPreviewActive && bottomToolbarRef.current) {
255	      setBoxWidth(bottomToolbarRef.current.getBoundingClientRect().width);
256	    }
257	  }, [boxWidth, isModeling, isPreviewActive]);
258	
259	  // Décalage x/y nécessaire pour que la colonne d'outils du mode Prévisualisation vienne se
260	  // coller au bord droit de l'écran, juste sous le ViewCube. `.container` (l'ancêtre direct)
261	  // est centré par `left: 50%` quel que soit l'état, donc son centre horizontal vaut
262	  // toujours exactement `window.innerWidth / 2` — inutile de mesurer le DOM, une formule
263	  // suffit et reste valable pendant toute animation. Le `top` de repos du conteneur est lui
264	  // fixe (posé par le CSS de `.container`/`.topToolbar`, pas par une mesure runtime).
265	  useEffect(() => {
266	    const recompute = () => {
267	      const restCenterX = window.innerWidth / 2;
268	      const targetCenterX = window.innerWidth - VIEWCUBE_RIGHT - PREVIEW_TOOLBAR_WIDTH / 2;
269	      const targetTop = VIEWCUBE_BOTTOM + PREVIEW_TOOLBAR_TOP_GAP;
270	
271	      setPreviewX(targetCenterX - restCenterX);
272	      setPreviewY(targetTop - BOTTOM_TOOLBAR_REST_TOP);
273	    };
274	
275	    recompute();
276	    window.addEventListener('resize', recompute);
277	    return () => window.removeEventListener('resize', recompute);
278	  }, []);
279	
280	  useEffect(() => {
281	    if (topToolbarRef.current && buttonRefs.current.size > 0) {
282	      const activeButtonKey = activeTool === 'layers' ? 'layers' : (activeTab === '3d-view' ? 'box' : activeTab);
283	      const activeButton = buttonRefs.current.get(activeButtonKey);
284	
285	      if (activeButton) {
286	        const toolbarRect = topToolbarRef.current.getBoundingClientRect();
287	        const buttonRect = activeButton.getBoundingClientRect();
288	
289	        setIndicatorStyle({
290	          width: buttonRect.width,
291	          height: buttonRect.height,
292	          left: buttonRect.left - toolbarRect.left,
293	          top: buttonRect.top - toolbarRect.top,
294	          opacity: 1,
295	        });
296	      } else {
297	        setIndicatorStyle((prev) => ({ ...prev, opacity: 0 }));
298	      }
299	    }
300	  }, [activeTab, activeTool]);
301	
302	  const iconVariants: Variants = {
303	    // Les icônes du mode cible n'apparaissent qu'UNE FOIS le reshape du conteneur terminé
304	    // (durée totale de l'animation de `.bottomToolbar`, voir CONTAINER_RESHAPE_DURATION) —
305	    // dans tous les sens de transition, pas seulement Prévisualisation→Modélisation. Sans ce
306	    // délai de base, les icônes du nouveau mode démarraient leur propre petit délai en
307	    // cascade (`i*0.04`) dès le changement de state React, bien avant que le conteneur ait
308	    // fini de se déplacer/déformer.
309	    visible: (i: number) => ({
310	      opacity: 1,
311	      y: 0,
312	      scale: 1,
313	      transition: {
314	        delay: CONTAINER_RESHAPE_DURATION + i * 0.04,
315	        duration: 0.3,
316	        ease: [0.16, 1, 0.3, 1] as const
317	      }
318	    }),
319	    // La sortie, elle, doit rester immédiate : les icônes du mode qu'on quitte doivent avoir
320	    // disparu AVANT que le conteneur ne commence à se déformer (cf. keyframes `times` de
321	    // `.bottomToolbar` : vidage sur les premiers 45%, déformation sur les 55% restants).
322	    hidden: (i: number) => ({
323	      opacity: 0,
324	      y: 15,
325	      scale: 0.95,
326	      transition: {
327	        delay: i * 0.04,
328	        duration: 0.25,
329	        ease: [0.25, 1, 0.5, 1] as const
330	      }
331	    })
332	  };
333	
334	  return (
335	    <div className={styles.container} data-apex-chrome-panel>
336	      {/* Top Toolbar (Navigation & Main Views) */}
337	      <div
338	        ref={topToolbarRef}
339	        className={clsx(styles.toolbar, styles.topToolbar)}
340	      >
341	        <div className={styles.activeIndicator} style={indicatorStyle}></div>
342	
343	        <CustomTooltip content="Apex Slicer Studio" description="Logiciel de préparation et de découpe 3D haute performance pour l'impression additive professionnelle.">
344	          <div className={styles.logoContainer}>
345	            <img src="/logo.svg" alt="Logo" className={styles.logoImg} />
346	          </div>
347	        </CustomTooltip>
348	
349	        <div className={styles.topSeparator} />
350	
351	        <CustomTooltip content="Vue 3D Perspective" description="Basculez sur l'espace de travail principal pour inspecter et manipuler vos modèles sur le plateau d'impression.">
352	          <button
353	            ref={(el) => { if (el) buttonRefs.current.set('box', el); }}
354	            className={clsx(styles.button, styles.topButton, {
355	              [styles.active]: activeTab === '3d-view' && !isPreviewActive,
356	            })}
357	            onClick={() => handleTopTabClick('box')}
358	          >
359	            <FileSliders size={22} />
360	            <span className={styles.topButtonLabel}>Préparation</span>
361	          </button>
362	        </CustomTooltip>
363	
364	        <CustomTooltip content="Prévisualisation" description="Visualisez le parcours de la buse et ajustez différents paramètres si cela ne vous convient pas.">
365	          <button
366	            ref={(el) => { if (el) buttonRefs.current.set('layers', el); }}
367	            className={clsx(styles.button, styles.topButton, {
368	              [styles.active]: isPreviewActive,
369	            })}
370	            onClick={handleLayerClick}
371	          >
372	            <Layers size={22} />
373	            <span className={styles.topButtonLabel}>Prévisualisation</span>
374	          </button>
375	        </CustomTooltip>
376	
377	        <CustomTooltip content="Modélisation" description="Accédez aux outils de modélisation et de préparation de votre modèle.">
378	          <button
379	            ref={(el) => { if (el) buttonRefs.current.set('settings', el); }}
380	            className={clsx(styles.button, styles.topButton, {
381	              [styles.active]: activeTab === 'settings',
382	            })}
383	            onClick={() => handleTopTabClick('settings')}
384	          >
385	            <Box size={22} />
386	            <span className={styles.topButtonLabel}>Modélisation</span>
387	          </button>
388	        </CustomTooltip>
389	
390	        <CustomTooltip content="Console Développeur" description="Inspectez les flux G-code générés en temps réel et les journaux de diagnostic système.">
391	          <button
392	            ref={(el) => { if (el) buttonRefs.current.set('developer', el); }}
393	            className={clsx(styles.button, styles.topButton, {
394	              [styles.active]: activeTab === 'developer',
395	            })}
396	            onClick={() => handleTopTabClick('developer')}
397	          >
398	            <Code size={22} />
399	            <span className={styles.topButtonLabel}>Dev</span>
400	          </button>
401	        </CustomTooltip>
402	      </div>
403	
404	      {/* Bottom Toolbar (Action, Manipulation 3D) — UN SEUL conteneur physique pour les 3
405	          modes (slicer / prévisualisation / modélisation) : il ne se démonte jamais, il se
406	          vide de ses icônes, se déplace et se déforme, puis affiche les icônes du mode
407	          suivant. En mode modélisation les boutons CAD ne sont pas rendus ici : ils vivent
408	          dans ModelingSidebar (toute la logique de features y reste), qui les injecte dans
409	          `modelingSlotRef` via un portail — même noeud DOM, contenu apporté par le
410	          propriétaire de sa logique. */}
411	      <motion.div
412	        ref={bottomToolbarRef}
413	        className={clsx(styles.toolbar, styles.bottomToolbar)}
414	        initial={false}
415	        animate={fromGeometry ? {
416	          // Toute transition (slicer ↔ prévisualisation, slicer ↔ modélisation) part
417	          // TOUJOURS de la forme réellement mesurée juste avant (`fromGeometry`) pour
418	          // rejoindre le gabarit du mode cible — un seul et même conteneur qui se vide de
419	          // ses icônes (cf. iconVariants), se déplace et se déforme, jamais deux
420	          // composants qui se croisent.
421	          x: [fromGeometry.x, fromGeometry.x, targetGeometry.x],
422	          y: [fromGeometry.y, fromGeometry.y, targetGeometry.y],
423	          width: [fromGeometry.width, fromGeometry.width, targetGeometry.width],
424	          height: [fromGeometry.height, fromGeometry.height, targetGeometry.height],
425	          borderRadius: [fromGeometry.borderRadius, fromGeometry.borderRadius, targetGeometry.borderRadius],
426	          opacity: 1,
427	          marginTop: 0
428	        } : {
429	          // État initial (avant toute transition jouée) : forme de repos du mode courant,
430	          // sans animation. "auto" tant que la largeur naturelle n'a pas encore été mesurée
431	          // (premier rendu), un nombre dès qu'elle l'est — évite un saut visuel une fois
432	          // `boxWidth` connu puisque `targetGeometry.width` vaudra alors la même valeur.
433	          x: targetGeometry.x,
434	          y: targetGeometry.y,
435	          width: isModeling || boxWidth !== null ? targetGeometry.width : "auto",
436	          height: targetGeometry.height,
437	          borderRadius: targetGeometry.borderRadius,
438	          opacity: 1,
439	          marginTop: 0
440	        }}
441	        transition={{
442	          duration: CONTAINER_RESHAPE_DURATION,
443	          times: [0, 0.45, 1],
444	          ease: [0.25, 1, 0.5, 1]
445	        }}
446	        style={{ originX: 0.5, originY: 0.5, pointerEvents: 'auto' }}
447	      >
448	        <motion.div custom={0} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
449	          <CustomTooltip content="Outil de Sélection" description="Cliquez sur n'importe quel modèle 3D sur le plateau pour le sélectionner et afficher ses propriétés.">
450	            <button
451	              className={clsx(styles.button, styles.bottomButton, {
