462	          <CustomTooltip content="Outil de Déplacement (Move - M)" description="Affichez les gizmos directionnels pour repositionner précisément l'objet sur le plateau d'impression. (Raccourci : M)">
463	            <button
464	              className={clsx(styles.button, styles.bottomButton, {
465	                [styles.active]: activeTool === 'move',
466	              })}
467	              onClick={() => handleToolClick('move')}
468	            >
469	              <Move3d size={16} />
470	            </button>
471	          </CustomTooltip>
472	        </motion.div>
473	
474	        <motion.div custom={2} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
475	          <CustomTooltip content="Outil de Rotation (Rotate - R)" description="Faites pivoter le modèle selon les axes X, Y et Z pour optimiser son orientation de contact. (Raccourci : R)">
476	            <button
477	              className={clsx(styles.button, styles.bottomButton, {
478	                [styles.active]: activeTool === 'rotate',
479	              })}
480	              onClick={() => handleToolClick('rotate')}
481	            >
482	              <RotateCw size={16} />
483	            </button>
484	          </CustomTooltip>
485	        </motion.div>
486	
487	        <motion.div custom={3} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
488	          <CustomTooltip content="Outil de Mise à l'échelle (Scale - S)" description="Modifiez la taille et les proportions du modèle 3D sur le plateau d'impression. (Raccourci : S)">
489	            <button
490	              className={clsx(styles.button, styles.bottomButton, {
491	                [styles.active]: activeTool === 'scale',
492	              })}
493	              onClick={() => handleToolClick('scale')}
494	            >
495	              <Maximize size={16} />
496	            </button>
497	          </CustomTooltip>
498	        </motion.div>
499	
500	        <motion.div custom={4} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
501	          <CustomTooltip content="Outil Texture & Matériau (Texture - T)" description="Sélectionnez et éditez les textures et propriétés de matériaux du modèle actif. (Raccourci : T)">
502	            <button
503	              className={clsx(styles.button, styles.bottomButton, {
504	                [styles.active]: activeTool === 'texture',
505	              })}
506	              onClick={() => handleToolClick('texture')}
507	            >
508	              <Palette size={16} />
509	            </button>
510	          </CustomTooltip>
511	        </motion.div>
512	
513	        <motion.div custom={5} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
514	          <div className={styles.separator} />
515	        </motion.div>
516	
517	        <motion.div custom={6} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
518	          <CustomTooltip content="Réinitialiser la Caméra" description="Remettez la caméra dans sa position isométrique par défaut face au plateau.">
519	            <button
520	              className={clsx(styles.button, styles.bottomButton)}
521	              onClick={() => window.dispatchEvent(new CustomEvent('apex-reset-camera'))}
522	            >
523	              <Eye size={16} />
524	            </button>
525	          </CustomTooltip>
526	        </motion.div>
527	
528	        <motion.div custom={7} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
529	          <CustomTooltip content="Ajuster à l'Écran (Fit)" description="Zoomez et recentrez la vue automatiquement sur le modèle sélectionné.">
530	            <button
531	              className={clsx(styles.button, styles.bottomButton)}
532	              onClick={() => window.dispatchEvent(new CustomEvent('apex-fit-screen'))}
533	            >
534	              <Maximize2 size={16} />
535	            </button>
536	          </CustomTooltip>
537	        </motion.div>
538	
539	        <motion.div custom={8} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
540	          <div className={styles.separator} />
541	        </motion.div>
542	
543	        <motion.div custom={9} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
544	          <CustomTooltip content="Importer un Modèle 3D (.stl, .glb, .gltf)" description="Ouvrez le sélecteur de fichiers pour charger un nouveau fichier 3D avec textures sur le plateau.">
545	            <button
546	              className={clsx(styles.button, styles.bottomButton, styles.uploadActionButton)}
547	              onClick={handleUploadClick}
548	            >
549	              <Upload size={16} />
550	            </button>
551	          </CustomTooltip>
552	        </motion.div>
553	
554	        {/* Mode modélisation : mêmes noeud et animation de conteneur que le mode slicer —
555	            seul le contenu diffère. Les boutons CAD eux-mêmes (logique de features) sont
556	            possédés par ModelingSidebar, qui les injecte ici via un portail (voir
557	            modelingSlotRef) plutôt que d'être dupliqués ou recréés dans ce composant. */}
558	        <motion.div
559	          custom={0}
560	          variants={iconVariants}
561	          animate={isModeling ? "visible" : "hidden"}
562	          initial="hidden"
563	          ref={modelingSlotRef}
564	          id="apex-modeling-toolbar-slot"
565	          className={styles.modelingSlot}
566	        />
567	
568	        <input
569	          type="file"
570	          ref={fileInputRef}
571	          style={{ display: 'none' }}
572	          accept=".stl,.glb,.gltf"
573	          onChange={(e) => {
574	            if (e.target.files?.[0]) {
575	              window.dispatchEvent(
576	                new CustomEvent('apex-import-model', {
577	                  detail: e.target.files[0],
578	                })
579	              );
580	            }
581	            // Réinitialise la valeur pour pouvoir réimporter exactement le même fichier
582	            // à la suite (sinon le navigateur ne redéclenche pas onChange).
583	            e.target.value = '';
584	          }}
585	        />
586	      </motion.div>
587	    </div>
588	  );
