620	          du bas ('forward'), ou l'inverse à la sortie ('reverse', même timeline jouée à l'envers).
621	          Le verre animé part/finit exactement sur la géométrie de la pilule et des deux panneaux
622	          ci-dessous, qui le remplacent une fois l'animation terminée. */}
623	      {previewMorphPhase && (
624	        <LiquidGlassMorph
625	          key={previewMorphPhase}
626	          left={PANEL_LEFT}
627	          top={PILL_TOP}
628	          width={PREVIEW_W}
629	          height={previewGeo.stageH}
630	          duration={PREVIEW_MORPH_MS}
631	          pathAt={previewPathAt}
632	          reverse={previewMorphPhase === 'reverse'}
633	          onDone={() => {
634	            if (previewMorphPhase === 'reverse') {
635	              previewActiveRef.current = false;
636	              setPreviewActive(false);
637	              setPreviewPanelsBorn(false);
638	            } else {
639	              setPreviewPanelsBorn(true);
640	            }
641	            setPreviewMorphPhase(null);
642	          }}
643	        />
644	      )}
645	
646	      {/* Panneaux de Prévisualisation, nés de la mitose : contenu à brancher plus tard. Pas
647	          d'animation d'entrée/sortie propre en temps normal — leur verre est identique à la
648	          dernière image du morphing ; ils s'effacent (.morphing) dès que la fusion inverse démarre,
649	          plutôt que de se démonter d'un coup. Exceptions, symétriques, jamais de refusion avec le
650	          panneau du haut (qui, lui, se transforme ailleurs — cf. ModelingSidebar) : le panneau du
651	          bas joue son propre fondu-glissement piloté directement par `animate` (JAMAIS par `exit` —
652	          `leavingToModeling` devient vrai dès le CLIC, ~900ms avant que ce composant ne démonte
653	          réellement à `onCovered` sous le rideau ; un `exit` ne jouerait qu'à ce moment bien trop
654	          tardif, invisible). Toujours le MÊME élément (jamais de changement de `key`/type), pour
655	          qu'`animate` puisse réagir à `leavingToModeling` sans jamais démonter/remonter. */}
656	      {previewActive && previewPanelsBorn && (
657	        <React.Fragment key="preview-panels">
658	          <div
659	            className={clsx(styles.previewPanelUpper, { [styles.morphing]: previewMorphPhase === 'reverse' })}
660	          />
661	          <motion.div
662	            className={clsx(styles.previewPanelLower, { [styles.morphing]: previewMorphPhase === 'reverse' })}
663	            initial={wasInitialPreviewActive ? { opacity: 0, x: -20 } : false}
664	            animate={{
665	              opacity: leavingToModeling ? 0 : 1,
666	              x: leavingToModeling ? -20 : 0,
667	              transition: { duration: FROM_PREVIEW_FADE_MS / 1000, ease: 'easeInOut' },
668	            }}
669	          />
670	        </React.Fragment>
671	      )}
672	
673	      {/* Menu de catégorie : la pilule enfante le panneau (ouverture) ou le réabsorbe (fermeture,
674	          même timeline jouée à l'envers). */}
675	      {morphPhase && (
676	        <LiquidGlassMorph
677	          key={morphPhase}
678	          left={PANEL_LEFT}
679	          top={PILL_TOP}
680	          width={MENU_W}
681	          height={MENU_STAGE_H}
682	          duration={MENU_MORPH_MS}
683	          pathAt={menuPathAt}
684	          reverse={morphPhase === 'merging'}
685	          onDone={() => {
686	            if (morphPhase === 'merging') onSelectCategory(null);
687	            setMorphPhase(null);
688	          }}
689	        />
690	      )}
691	
692	      <AnimatePresence>
693	        {activeCatData && !activeCatData.disabled && (
694	          <>
695	            {/* Toujours ouvert/fermé par un morphing : pas d'animation d'entrée ni de sortie
696	                propre, le verre animé en tient lieu (.morphing masque le fond de ce panneau et
697	                estompe son contenu pendant ce temps). */}
698	            <motion.div
699	              ref={menuContainerRef}
700	              className={clsx(styles.fusionMenuContainer, {
701	                [styles.morphing]: morphPhase !== null,
702	              })}
703	              initial={false}
704	              exit={{ opacity: 0 }}
705	              transition={{ duration: 0 }}
706	            >
707	              <div
708	                ref={contentRef}
709	                className={clsx(styles.fusionMenuContent, styles.contentInert)}
710	                onScroll={handleScroll}
711	              >
712	                {activeCatData.sections.map((section, idx) => (
713	                  <div key={idx} className={styles.sectionGroup}>
714	                    <h4 className={styles.sectionTitle}>{section.title}</h4>
715	                    <ul className={styles.itemsList}>
716	                      {section.items.map((item, iIdx) => (
717	                        <CustomTooltip key={iIdx} content="Arrive bientôt" description={item.description}>
718	                          <li className={styles.itemRow}>
719	                            <span className={styles.itemName}>
720	                              {item.isPatternDropdown ? `Motif de remplissage (${selectedPattern})` : item.label}
721	                            </span>
722	                            {item.isPatternDropdown ? (
723	                              <ChevronDown size={14} className="shrink-0 text-white/40 -rotate-90 ml-2" />
724	                            ) : (
725	                              <input
726	                                type="text"
727	                                defaultValue={item.defaultValue}
728	                                className={styles.itemInput}
729	                                readOnly
730	                                tabIndex={-1}
731	                              />
732	                            )}
733	                          </li>
734	                        </CustomTooltip>
735	                      ))}
736	                    </ul>
737	                  </div>
738	                ))}
739	              </div>
740	
741	              {hasScroll && (
742	                <div 
743	                  className={clsx(styles.externalScrollThumb, { [styles.dragging]: isDragging })}
744	                  onMouseDown={handleMouseDown}
745	                  style={{
746	                    height: `${thumbHeight}px`,
747	                    top: `${thumbTop}px`
748	                  }}
749	                />
750	              )}
751	            </motion.div>
752	
753	            {/* Pattern popup window next to the menu */}
754	            <AnimatePresence>
755	              {isPatternPopupOpen && (
756	                <motion.div
757	                  className={styles.patternPopup}
758	                  initial={{ opacity: 0, scale: 0.95, x: -10 }}
759	                  animate={{ opacity: 1, scale: 1, x: 0 }}
760	                  exit={{ opacity: 0, scale: 0.95, x: -10 }}
761	                  transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
762	                >
763	                  <div 
764	                    ref={patternContentRef}
765	                    className={styles.patternPopupContent}
766	                    onScroll={handlePatternScroll}
767	                  >
768	                    <div className={styles.sectionGroup}>
769	                      <h4 className={styles.sectionTitle}>Motifs de remplissage</h4>
770	                      <ul className={styles.itemsList}>
771	                        {INFILL_PATTERNS.map((pat, pIdx) => {
772	                          const isSelected = selectedPattern === pat.name;
773	                          return (
774	                            <CustomTooltip key={pIdx} content={pat.name} description={pat.description} key-override={pat.name}>
775	                              <li 
776	                                className={clsx(styles.patternItem, { [styles.activePattern]: isSelected })}
777	                                onClick={() => {
778	                                  setSelectedPattern(pat.name);
779	                                  setIsPatternPopupOpen(false);
780	                                }}
781	                              >
782	                                <span className={styles.itemName}>{pat.name}</span>
783	                                {isSelected && <Check size={14} className="text-[#00f0ff] shrink-0" />}
784	                              </li>
785	                            </CustomTooltip>
786	                          );
787	                        })}
788	                      </ul>
789	                    </div>
790	                  </div>
791	
792	                  {hasPatternScroll && (
793	                    <div 
794	                      className={clsx(styles.externalScrollThumb, { [styles.dragging]: isPatternDragging })}
795	                      onMouseDown={handlePatternMouseDown}
796	                      style={{
797	                        height: `${patternThumbHeight}px`,
798	                        top: `${patternThumbTop}px`
799	                      }}
800	                    />
801	                  )}
802	                </motion.div>
803	              )}
804	            </AnimatePresence>
805	          </>
806	        )}
807	      </AnimatePresence>
808	    </>
809	  );
810	};

