.dropdownTrigger {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  color: #00f0ff;
  font-size: 11px;
  padding: 4px 8px;
  transition: all 0.2s;
  max-width: 140px;
  pointer-events: none;
}

.dropdownText {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.patternPopup {
  position: fixed;
  left: calc(82px + 320px + 12px);
  top: calc(50% - 180px);
  width: 320px;
  max-height: 400px;
  border: none;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  border-radius: 16px;
  z-index: 1003;
  display: flex;
  flex-direction: column;
  overflow: visible;
  isolation: isolate;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.patternPopupContent {
  padding: 16px;
  overflow-y: scroll;
  max-height: 400px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-radius: 16px;

  &::-webkit-scrollbar {
    width: 0px;
    background: transparent;
  }
}

.patternItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.9);
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  transform: perspective(400px) translateZ(0px);

  &:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 255, 255, 0.2);
    color: #fff;
    transform: perspective(400px) translateZ(6px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  }

  &.activePattern {
    background: rgba(0, 240, 255, 0.2);
    border-color: #00f0ff;
    color: #00f0ff;
    font-weight: 600;
  }
}

