1	import { useEffect, useRef, useState } from 'react';
2	import { showError, showSuccess, showWarning } from '@/utils/toast';
3	import { parseGCode, stateAt, SUSPICIOUS_C_RANGE_DEG, type ParsedGCode } from '@/components/gcodeLayer';
4	
5	/**
6	 * Logique de l'espace Prévisualisation, sans interface : chargement de fichier G-code (dépôt sur
7	 * la fenêtre ou sélecteur), horloge de lecture et affichage des trajets à vide. Le rendu 3D est
8	 * fait par Viewport3D, piloté par les événements :
9	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
10	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
11	 *  - `apex-gcode-show-travel` { show } : affichage des trajets à vide.
12	 */
13	
14	export const GCODE_SPEED_OPTIONS = [25, 100, 400, 1600, 6400]; // mouvements par seconde
15	export const GCODE_ACCEPT = '.gcode,.gco,.g,.ngc';
16	const ACCEPTED_EXT = /\.(gcode|gco|g|ngc)$/i;
17	
18	export interface GCodeFileInfo {
19	  name: string;
20	  moves: number;
21	  extruding: number;
22	  minZ: number;
23	  maxZ: number;
24	  minC: number;
25	  maxC: number;
26	}
27	
28	const dispatchTime = (t: number) =>
29	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
30	
31	/** @param active Espace Prévisualisation affiché (active le dépôt de fichier, coupe la lecture sinon). */
32	export function useGCodePreview(active: boolean) {
33	  const parsedRef = useRef<ParsedGCode | null>(null);
34	  const tRef = useRef(0);
35	  const dragDepthRef = useRef(0);
36	
37	  const [fileInfo, setFileInfo] = useState<GCodeFileInfo | null>(null);
38	  const [t, setT] = useState(0);
39	  const [isPlaying, setIsPlaying] = useState(false);
40	  const [speed, setSpeed] = useState(GCODE_SPEED_OPTIONS[1]);
41	  const [showTravel, setShowTravel] = useState(false);
42	  const [isDragging, setIsDragging] = useState(false);
43	
44	  useEffect(() => {
45	    if (!active) setIsPlaying(false);
46	  }, [active]);
47	
48	  useEffect(() => {
49	    window.dispatchEvent(new CustomEvent('apex-gcode-show-travel', { detail: { show: showTravel } }));
50	  }, [showTravel]);
51	
52	  // Horloge de lecture : avance `t` à `speed` mouvements/s, pousse chaque image au viewport et
53	  // rafraîchit l'état React à ~20 Hz seulement.
54	  useEffect(() => {
55	    if (!isPlaying) return;
56	    const parsed = parsedRef.current;
57	    if (!parsed) return;
58	    const last = parsed.moves.length - 1;
59	    let raf = 0;
60	    let prev = performance.now();
61	    let sinceUiSync = 0;
62	    const step = (now: number) => {
63	      const dt = (now - prev) / 1000;
64	      prev = now;
65	      tRef.current = Math.min(last, tRef.current + speed * dt);
66	      dispatchTime(tRef.current);
67	      sinceUiSync += dt;
68	      if (tRef.current >= last) {
69	        setT(last);
70	        setIsPlaying(false);
71	        return;
72	      }
73	      if (sinceUiSync > 1 / 20) {
74	        sinceUiSync = 0;
75	        setT(tRef.current);
76	      }
77	      raf = requestAnimationFrame(step);
78	    };
79	    raf = requestAnimationFrame(step);
80	    return () => cancelAnimationFrame(raf);
81	  }, [isPlaying, speed]);
82	
83	  const loadFile = async (file: File) => {
84	    if (!ACCEPTED_EXT.test(file.name)) {
85	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
86	      return;
87	    }
88	    let parsed: ParsedGCode;
89	    try {
90	      parsed = parseGCode(await file.text());
91	    } catch {
92	      showError('Impossible de lire ce fichier G-code.');
93	      return;
94	    }
95	    if (parsed.moves.length < 2) {
96	      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
97	      return;
98	    }
99	
100	    parsedRef.current = parsed;
101	    const last = parsed.moves.length - 1;
102	    tRef.current = last;
103	    setIsPlaying(false);
104	    setT(last);
105	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
106	
107	    setFileInfo({
108	      name: file.name,
109	      moves: parsed.moves.length,
110	      extruding: parsed.extrudingCount,
111	      minZ: parsed.minZ,
112	      maxZ: parsed.maxZ,
113	      minC: parsed.minC,
114	      maxC: parsed.maxC,
115	    });
116	
117	    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
118	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
119	    } else {
120	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
121	    }
122	  };
123	
124	  /** Ouvre le sélecteur de fichier système (sans élément `<input>` dans l'interface). */
125	  const openFilePicker = () => {
126	    const input = document.createElement('input');
127	    input.type = 'file';
128	    input.accept = GCODE_ACCEPT;
129	    input.onchange = () => {
130	      const file = input.files?.[0];
131	      if (file) loadFile(file);
132	    };
133	    input.click();
134	  };
135	
136	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
137	  // souris pour la caméra, aucun élément d'interface n'a donc besoin de capter le dépôt.
138	  useEffect(() => {
139	    if (!active) return;
140	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
141	    const onDragEnter = (e: DragEvent) => {
142	      if (!hasFiles(e)) return;
143	      e.preventDefault();
144	      dragDepthRef.current++;
145	      setIsDragging(true);
146	    };
147	    const onDragOver = (e: DragEvent) => {
148	      if (!hasFiles(e)) return;
149	      e.preventDefault();
150	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
151	    };
152	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
153	    const onDragLeave = (e: DragEvent) => {
154	      if (!hasFiles(e)) return;
155	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
156	      if (dragDepthRef.current === 0) setIsDragging(false);
157	    };
158	    const onDrop = (e: DragEvent) => {
159	      if (!hasFiles(e)) return;
160	      e.preventDefault();
161	      dragDepthRef.current = 0;
162	      setIsDragging(false);
163	      const file = e.dataTransfer?.files?.[0];
164	      if (file) loadFile(file);
165	    };
166	    window.addEventListener('dragenter', onDragEnter);
167	    window.addEventListener('dragover', onDragOver);
168	    window.addEventListener('dragleave', onDragLeave);
169	    window.addEventListener('drop', onDrop);
170	    return () => {
171	      window.removeEventListener('dragenter', onDragEnter);
172	      window.removeEventListener('dragover', onDragOver);
173	      window.removeEventListener('dragleave', onDragLeave);
174	      window.removeEventListener('drop', onDrop);
175	      dragDepthRef.current = 0;
176	      setIsDragging(false);
177	    };
178	  }, [active]);
179	
180	  /** Place la lecture sur l'index de mouvement `value` (fractionnaire) et met la lecture en pause. */
181	  const seek = (value: number) => {
182	    setIsPlaying(false);
183	    tRef.current = value;
184	    setT(value);
185	    dispatchTime(value);
186	  };
187	
188	  /** Lecture/pause ; repart du début si la lecture est au bout. */
189	  const togglePlay = () => {
190	    const parsed = parsedRef.current;
191	    if (!parsed) return;
192	    if (!isPlaying && tRef.current >= parsed.moves.length - 1) seek(0);
193	    setIsPlaying(!isPlaying);
194	  };
195	
196	  const parsed = parsedRef.current;
197	  /** État machine interpolé (r, c, z, b) à la position de lecture. */
198	  const current = parsed ? stateAt(parsed.moves, t) : null;
199	  /** Mouvement en cours d'exécution (pour savoir s'il extrude). */
200	  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
201	  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;
202	
203	  return {
204	    fileInfo,
205	    t,
206	    lastIndex,
207	    current,
208	    currentMove,
209	    isPlaying,
210	    togglePlay,
211	    seek,
212	    speed,
213	    setSpeed,
214	    showTravel,
215	    setShowTravel,
216	    isDragging,
217	    loadFile,
218	    openFilePicker,
219	  };
220	}
221

