import * as BABYLON from 'babylonjs';

/**
 * G-code polaire 4 axes de l'Apex : parseur + calque Babylon de prévisualisation.
 *
 * Ce n'est PAS un G-code cartésien de slicer classique : une seule commande de déplacement,
 * `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
