// Barre de lecture G-code (espace Prévisualisation) : même verre que les autres panneaux
// flottants (.previewPanelUpper/.previewPanelLower dans CategoriesSidebar.module.scss,
// .categoriesToolbar) pour rester cohérente avec le reste du chrome. Prend la même emprise
// horizontale que la barre de statut (left-4/right-24 dans Index.tsx) pour s'aligner avec elle.
.bar {
  position: absolute;
  left: 16px;
  right: 96px;
  bottom: 16px;
  z-index: 40;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  border-radius: 14px;
  border: none;
  isolation: isolate;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  pointer-events: auto;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.playButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  background: rgba(0, 240, 255, 0.14);
  border: none;
  border-radius: 9px;
  color: #00f0ff;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);

  &:hover:not(:disabled) {
    background: rgba(0, 240, 255, 0.24);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

.scrubGroup {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1 1 auto;
  min-width: 0;
}

.scrubTrack {
  position: relative;
  height: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  cursor: pointer;

  &.disabledTrack {
    cursor: default;
  }
}

.scrubFill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(0, 240, 255, 0.5), #00f0ff);
  pointer-events: none;
}

.scrubInput {
  position: absolute;
  inset: -6px 0;
  width: 100%;
  height: 16px;
  margin: 0;
  opacity: 0;
  cursor: pointer;

  &:disabled {
    cursor: default;
  }
}

.scrubMeta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.fileName {
  color: rgba(255, 255, 255, 0.75);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 40%;
}

.separator {
  width: 1px;
  height: 22px;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.12);
}

.speedSelect {
  flex: 0 0 auto;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  color: #00f0ff;
  font-size: 11px;
  padding: 4px 6px;
  outline: none;
  cursor: pointer;

  &:focus {
    border-color: #00f0ff;
    box-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
