          <CustomTooltip content="Vitesse de lecture" description="Nombre de mouvements simulés par seconde pendant la lecture.">
            <select
              className={styles.speedSelect}
              value={speed}
              onChange={(e) => setSpeed(Number(e.target.value))}
            >
              {GCODE_SPEED_OPTIONS.map((opt) => (
                <option key={opt} value={opt}>{opt}x</option>
              ))}
            </select>
          </CustomTooltip>

          <CustomTooltip content="Trajets à vide" description="Affiche ou masque les déplacements de la buse sans extrusion.">
            <button
              className={`${styles.travelToggle} ${showTravel ? styles.travelActive : ''}`}
              onClick={() => setShowTravel(!showTravel)}
            >
              <Route size={16} />
            </button>
          </CustomTooltip>

          <div className={styles.separator} />

          <CustomTooltip content="Ouvrir un fichier G-code" description="Sélectionnez un fichier .gcode, .gco, .g ou .ngc à prévisualiser.">
            <button className={styles.browseButton} onClick={openFilePicker}>
              <FolderOpen size={14} />
              Parcourir
            </button>
          </CustomTooltip>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

