import { useGCodePreview } from '@/hooks/use-gcode-preview';
import styles from './GCodePreview.module.scss';

/**
 * Espace Prévisualisation, partie viewport : toute la logique (chargement, dépôt de fichier,
 * lecture, trajets à vide) est dans `useGCodePreview`. Ce composant reste monté à l'intérieur de
 * `main` (borné à l'espace 3D), donc sous le rideau de transition (SpaceTransitionOverlay, z-index 30) qui ne
 * doit couvrir que le viewport — voir Index.tsx.
 *
 * Les panneaux d'interface (mitose Qualité/Solidité-like) sont dans GCodePreviewPanels, monté à
 * la racine à côté de CategoriesSidebar : `position: fixed` hors de `main`, comme tous les autres
 * panneaux fixes, pour rester visibles par-dessus le rideau au lieu d'être masqués avec lui.
 */

interface GCodePreviewProps {
  /** Espace Prévisualisation affiché. */
  active: boolean;
}

export const GCodePreview: React.FC<GCodePreviewProps> = ({ active }) => {
  // Appelé même quand l'espace est masqué, pour garder le fichier et la position de lecture.
  const preview = useGCodePreview(active);
  void preview;

  if (!active) return null;

  return <div className={styles.container} />;
};

