  justify-content: space-between;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.fileName {
  color: rgba(255, 255, 255, 0.75);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 40%;
}

.separator {
  width: 1px;
  height: 22px;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.12);
}

.speedSelect {
  flex: 0 0 auto;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 6px;
  color: #00f0ff;
  font-size: 11px;
  padding: 4px 6px;
  outline: none;
  cursor: pointer;

  &:focus {
    border-color: #00f0ff;
    box-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
  }
}

.travelToggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  border-radius: 8px;
  color: rgba(255, 255, 255, 0.55);
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    color: rgba(255, 255, 255, 0.9);
    background: rgba(255, 255, 255, 0.1);
  }

  &.travelActive {
    background: rgba(0, 240, 255, 0.18);
    color: #00f0ff;
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }
}

.browseButton {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  border-radius: 8px;
  padding: 0 10px;
