  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);

  &:hover:not(:disabled) {
    background: rgba(0, 240, 255, 0.24);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

.scrubGroup {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1 1 auto;
  min-width: 0;
}

.scrubTrack {
  position: relative;
  height: 2px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  cursor: pointer;

  &.disabledTrack {
    cursor: default;
  }
}

.scrubFill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(0, 240, 255, 0.5), #00f0ff);
  pointer-events: none;
}

.scrubInput {
  position: absolute;
  inset: -6px 0;
  width: 100%;
  height: 16px;
  margin: 0;
  opacity: 0;
  cursor: pointer;

  &:disabled {
    cursor: default;
  }
}

.scrubMeta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 8px;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.fileName {
  color: rgba(255, 255, 255, 0.75);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 40%;
}

.separator {
  width: 1px;
  height: 9px;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.12);
}

.speedSelect {
  flex: 0 0 auto;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 3px;
  color: #00f0ff;
  font-size: 8px;
  padding: 1px 3px;
  outline: none;
  cursor: pointer;

  &:focus {
    border-color: #00f0ff;
    box-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
  }
}

.travelToggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  border-radius: 3px;
  color: rgba(255, 255, 255, 0.55);
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    color: rgba(255, 255, 255, 0.9);
    background: rgba(255, 255, 255, 0.1);
  }

  &.travelActive {
    background: rgba(0, 240, 255, 0.18);
    color: #00f0ff;
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }
}

.browseButton {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  border-radius: 3px;
  padding: 0 4px;
  height: 12px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
    background: rgba(255, 255, 255, 0.12);
  }
}

.emptyLabel {
  flex: 1 1 auto;
  font-size: 8px;
  color: rgba(255, 255, 255, 0.4);
}

