1	import React from 'react';
2	import { motion, AnimatePresence } from 'framer-motion';
3	import { Play, Pause, FolderOpen, Route } from 'lucide-react';
4	import { CustomTooltip } from './CustomTooltip';
5	import { GCODE_SPEED_OPTIONS, type GCodeFileInfo } from '@/hooks/use-gcode-preview';
6	import styles from './GCodePreviewBar.module.scss';
7	
8	interface GCodePreviewBarProps {
9	  /** Espace Prévisualisation affiché — pilote l'apparition/disparition de la barre elle-même. */
10	  active: boolean;
11	  fileInfo: GCodeFileInfo | null;
12	  t: number;
13	  lastIndex: number;
14	  isPlaying: boolean;
15	  togglePlay: () => void;
16	  seek: (value: number) => void;
17	  speed: number;
18	  setSpeed: (speed: number) => void;
19	  showTravel: boolean;
20	  setShowTravel: (show: boolean) => void;
21	  openFilePicker: () => void;
22	}
23	
24	/**
25	 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
26	 * affichage des trajets à vide et import de fichier. Toute la logique vient de
27	 * `useGCodePreview` (voir GCodePreview.tsx, qui possède le hook et transmet ses props ici) — ce
28	 * composant ne fait que l'afficher.
29	 *
30	 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
31	 * comme le panneau du bas de CategoriesSidebar (cf. FROM_PREVIEW_FADE_MS), mais vertical plutôt
32	 * qu'horizontal puisque cette barre vient du bord bas de l'écran plutôt que du bord gauche.
33	 */
34	export const GCodePreviewBar: React.FC<GCodePreviewBarProps> = ({
35	  active,
36	  fileInfo,
37	  t,
38	  lastIndex,
39	  isPlaying,
40	  togglePlay,
41	  seek,
42	  speed,
43	  setSpeed,
44	  showTravel,
45	  setShowTravel,
46	  openFilePicker,
47	}) => {
48	  const hasFile = !!fileInfo;
49	  const progress = lastIndex > 0 ? (t / lastIndex) * 100 : 0;
50	
51	  return (
52	    <AnimatePresence>
53	      {active && (
54	        <motion.div
55	          className={styles.bar}
56	          data-apex-chrome-panel
57	          initial={{ opacity: 0, y: 40 }}
58	          animate={{ opacity: 1, y: 0 }}
59	          exit={{ opacity: 0, y: 40 }}
60	          transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
61	        >
62	          <CustomTooltip
63	            content={isPlaying ? 'Pause' : 'Lecture'}
64	            description="Lance ou met en pause la lecture animée du parcours de la buse."
65	          >
66	            <button
67	              className={styles.playButton}
68	              onClick={togglePlay}
69	              disabled={!hasFile}
70	            >
71	              {isPlaying ? <Pause size={8} /> : <Play size={8} />}
72	            </button>
73	          </CustomTooltip>
74	
75	          {hasFile ? (
76	            <div className={styles.scrubGroup}>
77	              <div className={styles.scrubTrack}>
78	                <div className={styles.scrubFill} style={{ width: `${progress}%` }} />
79	                <input
80	                  type="range"
81	                  className={styles.scrubInput}
82	                  min={0}
83	                  max={lastIndex}
84	                  step={0.001}
85	                  value={t}
86	                  onChange={(e) => seek(Number(e.target.value))}
87	                />
88	              </div>
89	              <div className={styles.scrubMeta}>
90	                <span className={styles.fileName}>{fileInfo.name}</span>
91	                <span>{Math.round(t)} / {lastIndex} mouvements</span>
92	              </div>
93	            </div>
94	          ) : (
95	            <span className={styles.emptyLabel}>Déposez un fichier G-code ou parcourez vos fichiers</span>
96	          )}
97	
98	          <div className={styles.separator} />
99	
100	          <CustomTooltip content="Vitesse de lecture" description="Nombre de mouvements simulés par seconde pendant la lecture.">
101	            <select
102	              className={styles.speedSelect}
103	              value={speed}
104	              onChange={(e) => setSpeed(Number(e.target.value))}
105	            >
106	              {GCODE_SPEED_OPTIONS.map((opt) => (
107	                <option key={opt} value={opt}>{opt}x</option>
108	              ))}
109	            </select>
110	          </CustomTooltip>
111	
112	          <CustomTooltip content="Trajets à vide" description="Affiche ou masque les déplacements de la buse sans extrusion.">
113	            <button
114	              className={`${styles.travelToggle} ${showTravel ? styles.travelActive : ''}`}
115	              onClick={() => setShowTravel(!showTravel)}
116	            >
117	              <Route size={8} />
118	            </button>
119	          </CustomTooltip>
120	
121	          <div className={styles.separator} />
122	
123	          <CustomTooltip content="Ouvrir un fichier G-code" description="Sélectionnez un fichier .gcode, .gco, .g ou .ngc à prévisualiser.">
124	            <button className={styles.browseButton} onClick={openFilePicker}>
125	              <FolderOpen size={6} />
126	              Parcourir
127	            </button>
128	          </CustomTooltip>
129	        </motion.div>
130	      )}
131	    </AnimatePresence>
132	  );
133	};
134

