import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Play, Pause, FolderOpen, Route } from 'lucide-react';
import { CustomTooltip } from './CustomTooltip';
import { GCODE_SPEED_OPTIONS, type GCodeFileInfo } from '@/hooks/use-gcode-preview';
import styles from './GCodePreviewBar.module.scss';

interface GCodePreviewBarProps {
  /** Espace Prévisualisation affiché — pilote l'apparition/disparition de la barre elle-même. */
  active: boolean;
  fileInfo: GCodeFileInfo | null;
  t: number;
  lastIndex: number;
  isPlaying: boolean;
  togglePlay: () => void;
  seek: (value: number) => void;
  speed: number;
  setSpeed: (speed: number) => void;
  showTravel: boolean;
  setShowTravel: (show: boolean) => void;
  openFilePicker: () => void;
}

/**
 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
 * affichage des trajets à vide et import de fichier. Toute la logique vient de
 * `useGCodePreview` (voir GCodePreview.tsx, qui possède le hook et transmet ses props ici) — ce
 * composant ne fait que l'afficher.
 *
 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
 * comme le panneau du bas de CategoriesSidebar (cf. FROM_PREVIEW_FADE_MS), mais vertical plutôt
 * qu'horizontal puisque cette barre vient du bord bas de l'écran plutôt que du bord gauche.
 */
export const GCodePreviewBar: React.FC<GCodePreviewBarProps> = ({
  active,
  fileInfo,
  t,
  lastIndex,
  isPlaying,
  togglePlay,
  seek,
  speed,
  setSpeed,
  showTravel,
  setShowTravel,
  openFilePicker,
}) => {
  const hasFile = !!fileInfo;
  const progress = lastIndex > 0 ? (t / lastIndex) * 100 : 0;

  return (
    <AnimatePresence>
      {active && (
        <motion.div
          className={styles.bar}
          data-apex-chrome-panel
          initial={{ opacity: 0, y: 40 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: 40 }}
          transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
        >
          <CustomTooltip
            content={isPlaying ? 'Pause' : 'Lecture'}
            description="Lance ou met en pause la lecture animée du parcours de la buse."
          >
            <button
              className={styles.playButton}
              onClick={togglePlay}
              disabled={!hasFile}
            >
              {isPlaying ? <Pause size={8} /> : <Play size={8} />}
            </button>
          </CustomTooltip>

          {hasFile ? (
            <div className={styles.scrubGroup}>
              <div className={styles.scrubTrack}>
                <div className={styles.scrubFill} style={{ width: `${progress}%` }} />
                <input
                  type="range"
                  className={styles.scrubInput}
                  min={0}
                  max={lastIndex}
                  step={0.001}
                  value={t}
                  onChange={(e) => seek(Number(e.target.value))}
                />
              </div>
              <div className={styles.scrubMeta}>
                <span className={styles.fileName}>{fileInfo.name}</span>
                <span>{Math.round(t)} / {lastIndex} mouvements</span>
              </div>
            </div>
          ) : (
            <span className={styles.emptyLabel}>Déposez un fichier G-code ou parcourez vos fichiers</span>
          )}

          <div className={styles.separator} />

          <CustomTooltip content="Vitesse de lecture" description="Nombre de mouvements simulés par seconde pendant la lecture.">
            <select
              className={styles.speedSelect}
              value={speed}
              onChange={(e) => setSpeed(Number(e.target.value))}
            >
              {GCODE_SPEED_OPTIONS.map((opt) => (
                <option key={opt} value={opt}>{opt}x</option>
              ))}
            </select>
          </CustomTooltip>

          <CustomTooltip content="Trajets à vide" description="Affiche ou masque les déplacements de la buse sans extrusion.">
            <button
              className={`${styles.travelToggle} ${showTravel ? styles.travelActive : ''}`}
              onClick={() => setShowTravel(!showTravel)}
            >
              <Route size={8} />
            </button>
          </CustomTooltip>

          <div className={styles.separator} />

          <CustomTooltip content="Ouvrir un fichier G-code" description="Sélectionnez un fichier .gcode, .gco, .g ou .ngc à prévisualiser.">
            <button className={styles.browseButton} onClick={openFilePicker}>
              <FolderOpen size={6} />
              Parcourir
            </button>
          </CustomTooltip>
        </motion.div>
      )}
    </AnimatePresence>
  );
};

