toolUseResult.originalFile:
// Barre de lecture G-code (espace Prévisualisation) : même verre que les autres panneaux
// flottants (.previewPanelUpper/.previewPanelLower dans CategoriesSidebar.module.scss,
// .categoriesToolbar) pour rester cohérente avec le reste du chrome. Rendue comme enfant flex de
// la même rangée que le statut du plateau (cf. Index.tsx) plutôt que positionnée
// indépendamment : elle occupe l'espace restant à droite de la pastille de statut, exactement là
// où se trouvait le rectangle vide.
// Dimensions réduites à 0.4x la hauteur et 0.8x la longueur d'origine : hauteur fixée
// explicitement (52px de base -> ~21px) puisque le conteneur se dimensionnait jusque-là par son
// contenu, et largeur passée de "occupe tout l'espace restant" (flex-grow) à 80% de cet espace
// (flex-basis) pour garder un dimensionnement relatif à la rangée plutôt qu'une valeur en dur.
.bar {
  position: relative;
  flex: 0 0 80%;
  min-width: 0;
  height: 21px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border-radius: 14px;
  border: none;
  isolation: isolate;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
  pointer-events: auto;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(10, 15, 26, 0.25);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }
}

.playButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  background: rgba(0, 240, 255, 0.14);
  border: none;
  border-radius: 4px;
  color: #00f0ff;
  cursor: pointer;
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);

  &:hover:not(:disabled) {
    background: rgba(0, 240, 255, 0.24);
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }

  &:disabled {
    opacity: 0.35;
    cursor: not-allowed;
  }
}

.scrubGroup {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1 1 auto;
  min-width: 0;
}

.scrubTrack {
  position: relative;
  height: 2px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  cursor: pointer;

  &.disabledTrack {
    cursor: default;
  }
}

.scrubFill {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(0, 240, 255, 0.5), #00f0ff);
  pointer-events: none;
}

.scrubInput {
  position: absolute;
  inset: -6px 0;
  width: 100%;
  height: 16px;
  margin: 0;
  opacity: 0;
  cursor: pointer;

  &:disabled {
    cursor: default;
  }
}

.scrubMeta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 8px;
  color: rgba(255, 255, 255, 0.45);
  white-space: nowrap;
}

.fileName {
  color: rgba(255, 255, 255, 0.75);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 40%;
}

.separator {
  width: 1px;
  height: 9px;
  flex: 0 0 auto;
  background: rgba(255, 255, 255, 0.12);
}

.speedSelect {
  flex: 0 0 auto;
  background: rgba(0, 0, 0, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 3px;
  color: #00f0ff;
  font-size: 8px;
  padding: 1px 3px;
  outline: none;
  cursor: pointer;

  &:focus {
    border-color: #00f0ff;
    box-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
  }
}

.travelToggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 12px;
  height: 12px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  border-radius: 3px;
  color: rgba(255, 255, 255, 0.55);
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    color: rgba(255, 255, 255, 0.9);
    background: rgba(255, 255, 255, 0.1);
  }

  &.travelActive {
    background: rgba(0, 240, 255, 0.18);
    color: #00f0ff;
    box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);
  }
}

.browseButton {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
  background: transparent;
  border: none;
  border-radius: 3px;
  padding: 0 4px;
  height: 12px;
  color: rgba(255, 255, 255, 0.7);
  font-size: 8px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
    background: rgba(255, 255, 255, 0.12);
  }
}

.emptyLabel {
  flex: 1 1 auto;
  font-size: 8px;
  color: rgba(255, 255, 255, 0.4);
}

