import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { type GCodeFileInfo } from '@/hooks/use-gcode-preview';
import styles from './GCodePreviewBar.module.scss';

interface GCodePreviewBarProps {
  /** Espace Prévisualisation affiché — pilote l'apparition/disparition de la barre elle-même. */
  active: boolean;
  fileInfo: GCodeFileInfo | null;
  t: number;
  lastIndex: number;
  isPlaying: boolean;
  togglePlay: () => void;
  seek: (value: number) => void;
  speed: number;
  setSpeed: (speed: number) => void;
  showTravel: boolean;
  setShowTravel: (show: boolean) => void;
  openFilePicker: () => void;
}

// Décalage vertical de repos par rapport à la rangée : les deux éléments (cette barre et la
// pastille de statut, cf. Index.tsx) sont centrés sur la même rangée flex (`items-center`), ce
// qui les alignait pile sur la même ligne de base. Une valeur négative fait flotter la barre
// légèrement plus haut que la pastille, sans la sortir de la rangée.
const REST_Y = -6;
// Distance de glissement à l'entrée/sortie, ajoutée à ce repos plutôt que comptée depuis 0 — sans
// ça l'animation partirait d'un point différent de son arrivée réelle.
const SLIDE_Y = 40;

/**
 * Barre de lecture de l'espace Prévisualisation : play/pause, curseur de progression, vitesse,
 * affichage des trajets à vide et import de fichier. Toute la logique vient de
 * `useGCodePreview` (voir Index.tsx, qui possède le hook et transmet ses props ici).
 *
 * Contenu volontairement laissé vide pour l'instant (cf. demande) : seuls la forme de verre et
 * son animation d'entrée/sortie sont branchées. Les props ci-dessus restent transmises pour ne
 * pas avoir à retoucher Index.tsx quand le contenu sera ajouté.
 *
 * Glissement-fondu depuis le bas de l'écran à l'entrée dans l'espace, et inverse à la sortie —
 * comme le panneau du bas de CategoriesSidebar (cf. FROM_PREVIEW_FADE_MS), mais vertical plutôt
 * qu'horizontal puisque cette barre vient du bord bas de l'écran plutôt que du bord gauche.
 */
export const GCodePreviewBar: React.FC<GCodePreviewBarProps> = ({ active }) => {
  return (
    <AnimatePresence>
      {active && (
        <motion.div
          className={styles.bar}
          data-apex-chrome-panel
          initial={{ opacity: 0, y: REST_Y + SLIDE_Y }}
          animate={{ opacity: 1, y: REST_Y }}
          exit={{ opacity: 0, y: REST_Y + SLIDE_Y }}
          transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
        />
      )}
    </AnimatePresence>
  );
};

