1	"use client";
2	
3	import React, { useEffect, useRef, useState } from 'react';
4	import { Sidebar } from '@/components/Sidebar';
5	import { FileSidebar } from '@/components/FileSidebar';
6	import { SliceSidebar } from '@/components/SliceSidebar';
7	import { CategoriesSidebar } from '@/components/CategoriesSidebar';
8	import { PrinterConfigSidebar } from '@/components/PrinterConfigSidebar';
9	import { AxisSidebar } from '@/components/AxisSidebar';
10	import { ModelingSidebar } from '@/components/ModelingSidebar';
11	import { TopRightMenu } from '@/components/TopRightMenu';
12	import { ModelStatusBox } from '@/components/ModelStatusBox';
13	import { ModelHoverTooltip } from '@/components/ModelHoverTooltip';
14	import { TextureEditorModal } from '@/components/TextureEditorModal';
15	import { SliceModal } from '@/components/SliceModal';
16	import { SlicingProgressModal } from '@/components/SlicingProgressModal';
17	import { ViewCube } from '@/components/ViewCube';
18	import { Viewport3D } from '@/components/Viewport3D';
19	import { SpaceTransitionOverlay } from '@/components/SpaceTransitionOverlay';
20	import { GCodePreview } from '@/components/GCodePreview';
21	import { GCodePreviewBar } from '@/components/GCodePreviewBar';
22	import { useGCodePreview } from '@/hooks/use-gcode-preview';
23	import { useAnimate } from 'framer-motion';
24	import { Box } from 'lucide-react';
25	import { showSuccess } from '@/utils/toast';
26	
27	interface ModelStatus {
28	  name: string;
29	  dimensions: { x: number; y: number; z: number } | null;
30	}
31	
32	const Index = () => {
33	  const [activeTab, setActiveTab] = useState<'3d-view' | 'settings' | 'developer'>('3d-view');
34	  const [activeCategory, setActiveCategory] = useState<string | null>(null);
35	  const [isPrinterConfigOpen, setIsPrinterConfigOpen] = useState(false);
36	  const [selectedPrinter, setSelectedPrinter] = useState('Prusa MK4');
37	  const [selectedFilament, setSelectedFilament] = useState('PLA Premium (eSUN / Prusament)');
38	  const [isSliceModalOpen, setIsSliceModalOpen] = useState(false);
39	  const [isSlicingProgressOpen, setIsSlicingProgressOpen] = useState(false);
40	  const [modelStatus, setModelStatus] = useState<ModelStatus | null>(null);
41	  const [isPreviewActive, setIsPreviewActive] = useState(false);
42	  const isPreviewActiveRef = useRef(isPreviewActive);
43	  isPreviewActiveRef.current = isPreviewActive;
44	  // Logique de l'espace Prévisualisation (chargement/lecture G-code) : appelée ici (et non dans
45	  // GCodePreview) car sa barre de lecture (GCodePreviewBar) partage la rangée du bas avec la
46	  // pastille de statut du plateau, ce qui demande que les deux soient des enfants directs du même
47	  // conteneur flex plutôt que des composants positionnés indépendamment.
48	  const gcodePreview = useGCodePreview(isPreviewActive);
49	  // Le temps que ModelingSidebar déforme sa propre silhouette entre la forme de la pilule/des deux
50	  // panneaux de Prévisualisation et sa forme normale — cf. le commentaire sur `onTabChange` plus
51	  // bas et le prop `morph` de ModelingSidebar. `null` = pas de morph en cours ; sinon, `direction`
52	  // indique le sens ('enter' : la pilule/Prévisualisation devient le panneau Modélisation, 'exit' :
53	  // l'inverse) et `fromPreview` l'état de Prévisualisation à l'autre bout du morph (pilule ou
54	  // panneaux Preview) — figé à l'instant du clic, lu depuis isPreviewActiveRef, PAS depuis
55	  // isPreviewActive : Sidebar mute ce dernier dans le même geste, avant qu'on ait la chance de lire
56	  // sa valeur de départ. Contrairement à l'ancienne approche (deux calques à synchroniser — un
57	  // verre animé séparé, puis le vrai panneau), c'est ICI le même élément, déjà affiché avec son
58	  // contenu réel, qui change de forme : plus de raccord entre deux éléments distincts, donc plus
59	  // de risque de clignotement à la jonction.
60	  const [modelingMorph, setModelingMorph] = useState<{ direction: 'enter' | 'exit'; fromPreview: boolean } | null>(null);
61	  // Vrai dès le CLIC vers Modélisation (cf. l'écouteur d'apex-entering-modeling plus bas), jamais
62	  // seulement à `onCovered` (~900ms plus tard, une fois le rideau refermé) : le fondu-glissement du
63	  // panneau du bas de Prévisualisation doit être visible EN TRANSPARENCE À TRAVERS le rideau qui
64	  // monte, pas caché derrière lui — contrairement au vrai changement d'onglet (`onTabChange`), qui
65	  // lui reste cadencé par `onCovered`. Redevient faux une fois le morph 'enter' effectivement lancé
66	  // (le panneau du bas a alors largement eu le temps de finir sa disparition, 260ms contre les
67	  // ~900ms d'attente du rideau).
68	  const [leavingToModeling, setLeavingToModeling] = useState(false);
69	  const [statusBarRef, animateStatusBar] = useAnimate<HTMLDivElement>();
70	  const prevPreviewActiveRef = useRef(isPreviewActive);
71	
72	  // Au changement d'espace, la barre d'aide (TopRightMenu) passe par le coin bas gauche, là où
73	  // se trouve la barre de statut : celle-ci se rentre sous le bord de l'écran juste avant
74	  // (0,2 → 0,45 s ; la barre d'aide démarre à 0,495 s) et ressort une fois la barre d'aide
75	  // arrivée (1,1 s), pour ne pas se faire recouvrir.
76	  useEffect(() => {
77	    if (prevPreviewActiveRef.current === isPreviewActive) return;
78	    prevPreviewActiveRef.current = isPreviewActive;
79	    if (!statusBarRef.current) return;
80	    animateStatusBar(
81	      statusBarRef.current,
82	      { y: [0, 0, 80, 80, 0] },
83	      { duration: 1.4, times: [0, 0.2 / 1.4, 0.45 / 1.4, 1.1 / 1.4, 1], ease: [0.25, 1, 0.5, 1] },
84	    );
85	  }, [isPreviewActive, animateStatusBar, statusBarRef]);
86	
87	  /** L'onglet « Modélisation » de la Sidebar porte la valeur 'settings'. */
88	  const isModeling = activeTab === 'settings';
89	
90	  // Une fois CategoriesSidebar (et son panneau du bas) effectivement démontée par le passage en
91	  // Modélisation, `leavingToModeling` peut redescendre : il n'a plus d'effet visuel à cet instant
92	  // (le fondu est terminé depuis longtemps), mais doit être prêt (`false`) pour un futur cycle.
93	  useEffect(() => {
94	    if (isModeling) setLeavingToModeling(false);
95	  }, [isModeling]);
96	
97	  // Vrai du début d'un morph de sortie de Modélisation jusqu'au commit qui le termine, où
98	  // CategoriesSidebar est remontée et le lit (une seule fois, à son montage). Remis à `false` juste
99	  // après, une fois ce montage passé.
100	  const [arrivingFromModeling, setArrivingFromModeling] = useState(false);
101	  useEffect(() => {
102	    if (!modelingMorph) setArrivingFromModeling(false);
103	  }, [modelingMorph]);
104	
105	  React.useEffect(() => {
106	    const handleModelSelected = (event: CustomEvent<{
107	      name: string | null;
108	      dimensions?: { x: number; y: number; z: number };
109	    }>) => {
110	      if (!event.detail?.name) {
111	        setModelStatus(null);
112	        return;
113	      }
114	
115	      setModelStatus({
116	        name: event.detail.name,
117	        dimensions: event.detail.dimensions ?? null,
118	      });
119	    };
120	
121	    const handleModelImported = (event: CustomEvent<File>) => {
122	      if (event.detail?.name) {
123	        setModelStatus({ name: event.detail.name, dimensions: null });
124	      }
125	    };
126	
127	    const handlePreviewToggled = (event: CustomEvent<{ active: boolean }>) => {
128	      setIsPreviewActive(!!event.detail?.active);
129	    };
130	
131	    // Dispatché par Sidebar.tsx (handleTopTabClick) au tout début du clic vers Modélisation, avant
132	    // même que le rideau plein écran ne commence à monter — cf. le commentaire sur
133	    // `leavingToModeling` plus haut.
134	    const handleEnteringModeling = () => setLeavingToModeling(true);
135	
136	    window.addEventListener('apex-mesh-selected', handleModelSelected as EventListener);
137	    window.addEventListener('apex-import-model', handleModelImported as EventListener);
138	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
139	    window.addEventListener('apex-entering-modeling', handleEnteringModeling);
140	
141	    return () => {
142	      window.removeEventListener('apex-mesh-selected', handleModelSelected as EventListener);
143	      window.removeEventListener('apex-import-model', handleModelImported as EventListener);
144	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
145	      window.removeEventListener('apex-entering-modeling', handleEnteringModeling);
146	    };
147	  }, []);
148	
149	  const handleSlice = () => {
150	    window.dispatchEvent(new CustomEvent('apex-request-slice-models'));
151	    setIsSliceModalOpen(true);
152	  };
153	
154	  const handleConfirmSlice = () => {
155	    window.dispatchEvent(new CustomEvent('apex-slice-all-models'));
156	    setIsSliceModalOpen(false);
157	    setIsSlicingProgressOpen(true);
158	  };
159	
160	  const handleSlicingFinished = () => {
161	    setIsSlicingProgressOpen(false);
162	    showSuccess("Slicing plate completed successfully!");
163	  };
164	
165	  const handleOpenModel = () => {
166	    showSuccess("Select an STL or GLB file to add a model.");
167	  };
168	
169	  const handleSaveProject = () => {
170	    showSuccess("Project saved successfully.");
171	  };
172	
173	  return (
174	    <div
175	      className="flex flex-col h-screen w-screen overflow-hidden select-none relative"
176	      style={{ backgroundColor: '#2a2d34' }}
177	    >
178	      <FileSidebar 
179	        onOpenModel={handleOpenModel}
180	        onSaveProject={handleSaveProject}
181	        onOpenSettings={() => setActiveTab('settings')}
182	        onOpenPrinterConfig={() => {
183	          setIsPrinterConfigOpen(!isPrinterConfigOpen);
184	          setActiveCategory(null);
185	        }}
186	        selectedPrinter={selectedPrinter}
187	        selectedFilament={selectedFilament}
188	      />
189	
190	      <ModelStatusBox />
191	      <ModelHoverTooltip />
192	      <TextureEditorModal />
193	      <SliceModal
194	        isOpen={isSliceModalOpen}
195	        onClose={() => setIsSliceModalOpen(false)}
196	        onConfirm={handleConfirmSlice}
197	      />
198	      <SlicingProgressModal
199	        isOpen={isSlicingProgressOpen}
200	        onClose={() => setIsSlicingProgressOpen(false)}
201	        onFinished={handleSlicingFinished}
202	      />
203	
204	      <Sidebar
205	        activeTab={activeTab}
206	        onTabChange={(tab, toPreview) => {
207	          // Passage vers ou hors de Modélisation : le rideau plein écran (déjà déclenché par
208	          // Sidebar avant cet appel, cf. playSpaceTransition) masque le changement de `main`,
209	          // pendant lequel ModelingSidebar (montée en permanence tant que isModeling ||
210	          // modelingMorph) joue le morph — cf. son prop `morph`.
211	          if (tab === 'settings' && !isModeling) {
212	            // L'état de départ (Préparation ou Prévisualisation) est lu MAINTENANT depuis
213	            // isPreviewActiveRef, avant que Sidebar ne le fasse passer à jour dans ce même geste.
214	            // Les éléments sans place en Modélisation ont déjà disparu depuis le clic
215	            // (apex-entering-modeling, ~900ms plus tôt) : la déformation peut commencer tout de
216	            // suite, dans le même commit que la bascule CategoriesSidebar → ModelingSidebar.
217	            setModelingMorph({ direction: 'enter', fromPreview: isPreviewActiveRef.current });
218	          } else if (tab !== 'settings' && isModeling) {
219	            // Sortie de Modélisation : `tab === 'box'` que ce soit vers Préparation ou vers
220	            // Prévisualisation (cf. handleLayerClick dans Sidebar.tsx, branche `entering`, qui
221	            // passe `toPreview: true`) — la destination ne peut donc pas se lire depuis `tab` seul.
222	            setModelingMorph({ direction: 'exit', fromPreview: !!toPreview });
223	            setArrivingFromModeling(true);
224	          }
225	          setActiveTab(tab === 'box' ? '3d-view' : tab);
226	          setIsPrinterConfigOpen(false);
227	        }}
228	        onOpenModel={handleOpenModel}
229	      />
230	
231	      <TopRightMenu />
232	      <AxisSidebar />
233	      <ViewCube />
234	
235	      {/* Les panneaux slicer et le panneau modélisation s'excluent mutuellement. La bascule se fait
236	          TOUJOURS dans un seul commit, par un rendu conditionnel simple — jamais via
237	          AnimatePresence, qui retarde le démontage de l'ancien côté (et en mode 'wait', le
238	          montage du nouveau) d'au moins une tâche, donc d'au moins une frame peinte. Toute
239	          l'animation visible est portée ailleurs : la déformation par ModelingSidebar (prop
240	          `morph`), les fondus par `animate` dès le clic. */}
241	      {isModeling || modelingMorph?.direction === 'exit' ? (
242	        <ModelingSidebar
243	          morph={
244	            modelingMorph
245	              ? { ...modelingMorph, onDone: () => setModelingMorph(null) }
246	              : undefined
247	          }
248	        />
249	      ) : (
250	          <>
251	            <CategoriesSidebar
252	              activeCategory={activeCategory}
253	              onSelectCategory={(cat) => {
254	                setActiveCategory(cat);
255	                if (cat) setIsPrinterConfigOpen(false);
256	              }}
257	              // Remonté à la fin d'un morph de sortie de Modélisation : ce composant doit apparaître
258	              // directement dans la forme que ModelingSidebar vient de prendre (pilule ou panneaux
259	              // de Prévisualisation), sans rejouer d'entrée ni de mitose. Ces deux props ne sont lues
260	              // qu'au montage (figées en interne).
261	              initialPreviewActive={isPreviewActive}
262	              arrivingFromModeling={arrivingFromModeling}
263	              leavingToModeling={leavingToModeling}
264	            />
265	
266	            <PrinterConfigSidebar
267	              isOpen={isPrinterConfigOpen}
268	              onClose={() => setIsPrinterConfigOpen(false)}
269	              selectedPrinter={selectedPrinter}
270	              onSelectPrinter={setSelectedPrinter}
271	              selectedFilament={selectedFilament}
272	              onSelectFilament={setSelectedFilament}
273	            />
274	
275	            <SliceSidebar onSlice={handleSlice} />
276	          </>
277	      )}
278	
279	      <main className="flex-1 flex flex-col relative overflow-hidden z-10 bg-transparent">
280	        <div className="flex-1 w-full h-full">
281	          <Viewport3D />
282	        </div>
283	
284	        {/* Espace Prévisualisation : interface du prévisualisateur G-code polaire. Le tracé
285	            lui-même est rendu par Viewport3D, dans la même scène que la Préparation. Toujours
286	            monté pour conserver le fichier chargé d'un aller-retour à l'autre. */}
287	        <GCodePreview active={isPreviewActive} />
288	
289	        {/* À l'intérieur de `main` (donc borné à l'espace 3D) et sous les panneaux `position:
290	            fixed` (sidebars, menus, tooltips, z-index 1000+) : le flou et le voile ne doivent
291	            couvrir que le viewport, jamais les éléments en superposition. */}
292	        <SpaceTransitionOverlay />
293	
294	        {/* Bottom status / stats overlay — au-dessus du rideau de transition (z-index 30) pour
295	            ne pas être flouté, comme les panneaux fixes. En Prévisualisation, la barre de lecture
296	            G-code (GCodePreviewBar) partage cette rangée avec la pastille de statut, occupant
297	            l'espace restant à droite d'elle. */}
298	        <div ref={statusBarRef} className="absolute bottom-4 left-4 right-24 z-40 flex items-center justify-start gap-3 pointer-events-none">
299	          <div className="bg-[rgba(10,15,26,0.25)] backdrop-blur-[4px] -webkit-backdrop-blur-[4px] border-none rounded-lg px-3 py-2 text-xs text-zinc-300 flex items-center space-x-4 pointer-events-auto shadow-[0_8px_32px_0_rgba(0,0,0,0.4),0_2px_8px_0_rgba(0,0,0,0.3)] shrink-0">
300	            {modelStatus ? (
301	              <>
302	                <span className="flex items-center"><Box className="w-3.5 h-3.5 mr-1.5 text-blue-400" /> {modelStatus.name}</span>
303	                {modelStatus.dimensions && (
304	                  <>
305	                    <span className="text-zinc-600">|</span>
306	                    <span>Dimensions: {modelStatus.dimensions.x.toFixed(1)} x {modelStatus.dimensions.z.toFixed(1)} x {modelStatus.dimensions.y.toFixed(1)} mm</span>
307	                  </>
308	                )}
309	                <span className="text-zinc-600">|</span>
310	                <span className="text-emerald-400 font-medium">Ready to slice</span>
311	              </>
312	            ) : (
313	              <span className="text-zinc-400">Aucun modèle sur le plateau</span>
314	            )}
315	          </div>
316	
317	          <GCodePreviewBar active={isPreviewActive} {...gcodePreview} />
318	        </div>
319	      </main>
320	    </div>
321	  );
322	};
323	
324	export default Index;

